import { Group, PlaneGeometry, MeshBasicNodeMaterial, TextureLoader } from 'three/webgpu';
import { texture, color, mul } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // --- Background plane ---
  const bgTexture = ctx.textureLoader.get(config.assets.imageUrl);
  bgTexture.wrapS = bgTexture.wrapT = 1000; // Repeat? Better clamp
  bgTexture.wrapS = bgTexture.wrapT = 1001; // ClampToEdge

  // Plane size derived from source rect aspect ratio
  const srcW = 512, srcH = 320;
  const planeWidth = 2;
  const planeHeight = planeWidth * (srcH / srcW);
  const bgGeom = new PlaneGeometry(planeWidth, planeHeight);
  const bgMat = new MeshBasicNodeMaterial({
    map: bgTexture,
    transparent: true,
    opacity: 1,
  });
  const bgMesh = new THREE.Mesh(bgGeom, bgMat);
  bgMesh.name = 'background';
  group.add(bgMesh);

  // --- Text plane ---
  const textColor = color('#16161d'); // ink
  const textMesh = createTextMesh({
    text: 'Pricing 1',
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 0.2, // subhead scene units
    color: textColor,
    align: 'center',
    anchor: 'center',
  });
  textMesh.position.set(0, 0, 0.001); // slight Z offset to avoid z-fighting
  textMesh.name = 'text';
  group.add(textMesh);

  // --- UserData handlers & cleanup ---
  group.userData.handlers = {};

  const materials = [bgMat, textMesh.material].filter(Boolean);
  const geometries = [bgGeom, textMesh.geometry].filter(Boolean);
  const textures = [bgTexture];

  group.userData.cleanup = () => {
    materials.forEach((m) => {
      if (m.dispose) m.dispose();
    });
    geometries.forEach((g) => {
      if (g.dispose) g.dispose();
    });
    textures.forEach((t) => {
      if (t.dispose) t.dispose();
    });
    // Kill any GSAP timelines (none in this node but for consistency)
    gsap.killTweensOf(group);
  };

  // Apply cinematic primitives (none specified)
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      ctx.primitives[prim.name](group, prim.params);
    });
  }

  return group;
}
